//! Core route/channel/private SQLite contracts; no physical or software audio worker.
use super::*;
async fn restart(mut f:Fixture)->Fixture {let(s,router)=reopened(&f).await;f.s=s;f.app=router;f}
async fn reconnect(f:&Fixture,p:&mut[Peer]) {
    for peer in p {
        let(tx,rx)=tokio::sync::mpsc::channel(32);peer.tx=tx.clone();peer.rx=rx;f.s.bridges.write().await.insert(peer.endpoint.clone(),tx.clone());f.s.bridge_owners.write().await.insert(peer.endpoint.clone(),auth::hash(&f.token));
        let mut filter=clock::Filter::default();let now=clock::now_ns();let mut reply=filter.probe(&peer.endpoint,now);reply["host_clock_id"]=json!(uuid::Uuid::new_v4().to_string());reply["t2_ns"]=json!(now+peer.offset as u64+1000);reply["t3_ns"]=json!(now+peer.offset as u64+2000);assert!(filter.accept(&reply,now+3000));
        f.s.endpoints.write().await.insert(peer.endpoint.clone(),json!({"id":peer.endpoint,"online":true,"capabilities":{"playback_instance":true,"scheduled_start_v1":true,"continuous_pcm":true,"host_clock_v1":true,"media_url_api_relative":true,"scheduled_queue_v1":true,"group_output_v2":true,"measured_listens_v2":true,"group_output_final_v2":true},"clock_calibration":filter.estimate(now+3000)}));f.s.clock_filters.write().await.insert(peer.endpoint.clone(),(tx,filter));
    }
}
async fn create()->(Fixture,Vec<Peer>,Value,Vec<Value>,Vec<Value>) {
    let f=Fixture::new().await;let(track,_)=f.add_audio().await;f.s.db.run(|c|{c.execute("UPDATE tracks SET duration=8.0,sample_rate=768000,bit_depth=32",[])?;Ok(())}).await.unwrap();let mut p=peers(&f,32).await;enable_v2(&f,&p).await;let mut req=request(&track,&p);req["measured_version"]=json!(2);req["queue"]=json!([track,track]);let(commands,_,commits)=begin_v2(&f,&mut p,&req,768000).await;(f,p,req,commands,commits)
}
async fn finals(f:&Fixture,p:&[Peer],req:&Value,commands:&[Value],commits:&[Value],frames:[u64;2]) {
    let path=format!("/api/v1/sync/starts/{}/final-receipts",req["request_id"].as_str().unwrap());
    for i in 0..2 {let body=receipt(&commands[i],&commits[i],&p[i],frames[i],json!([source(&commands[i],frames[i],false)]));let(status,value)=f.call("POST",&path,Some(body)).await;assert_eq!(status,StatusCode::OK,"{value}");if i==0{assert_eq!(f.call("GET",&path.replace("/final-receipts","/recovery"),None).await.1["available"],false);}}
}
#[tokio::test]
async fn group_early_final_v2_before_source_prepare_keeps_account_identity_and_zero_credit(){
    let f=Fixture::new().await;let(track,_)=f.add_audio().await;let mut p=peers(&f,16).await;enable_v2(&f,&p).await;
    assert_eq!(f.call("POST","/api/v1/auth/users",Some(json!({"username":"early-output","password":"correct-early-password"}))).await.0,StatusCode::OK);let(_,login)=f.call("POST","/api/v1/auth/login",Some(json!({"username":"early-output","password":"correct-early-password"}))).await;let other=login["token"].as_str().unwrap().to_owned();f.s.bridge_owners.write().await.insert(p[0].endpoint.clone(),auth::hash(&other));
    let mut req=request(&track,&p);req["measured_version"]=json!(2);let base=format!("/api/v1/sync/starts/{}",req["request_id"].as_str().unwrap());assert_eq!(f.call("POST","/api/v1/sync/starts",Some(req)).await.0,StatusCode::ACCEPTED);
    let commands=vec![receive(&mut p[0]).await,receive(&mut p[1]).await];assert_eq!(f.call("POST",&format!("{base}/control"),Some(json!({"request_id":uuid::Uuid::new_v4().to_string(),"action":"pause"}))).await.0,StatusCode::ACCEPTED);
    let mut bodies=Vec::new();for i in 0..2{assert_eq!(receive(&mut p[i]).await["type"],"cancel_start");let mut value=final_report_value(&commands[i],&json!({"deadline_host_ns":0}),0,json!([]));value["measured_version"]=json!(2);value["sample_rate"]=json!(0);value["gate"]["phase"]=json!("cancelled");report(&f,&p[i],value.clone()).await;bodies.push(json!({"request_id":uuid::Uuid::new_v4().to_string(),"endpoint_id":p[i].endpoint,"captured_at":chrono::Utc::now().timestamp_millis(),"captured_host_ns":1,"report":value}));}
    assert_eq!(f.call("GET",&base,None).await.1["phase"],"paused");let f=restart(f).await;let path=format!("{base}/final-receipts");
    assert_eq!(f.call("POST",&path,Some(bodies[0].clone())).await.0,StatusCode::FORBIDDEN);
    let mut invalid=bodies[0].clone();invalid["report"]["start"]["expires_host_ns"]=json!(1);assert_eq!(call(&f.app,"POST",&path,Some(&other),Some(invalid)).await.0,StatusCode::BAD_REQUEST);
    let mut invalid=bodies[0].clone();invalid["report"]["programme_frames_played"]=json!(1);assert_eq!(call(&f.app,"POST",&path,Some(&other),Some(invalid)).await.0,StatusCode::BAD_REQUEST);
    for i in 0..2{let token=if i==0{&other}else{&f.token};let(status,value)=call(&f.app,"POST",&path,Some(token),Some(bodies[i].clone())).await;assert_eq!(status,StatusCode::OK,"{value}");assert_eq!(call(&f.app,"POST",&path,Some(token),Some(bodies[i].clone())).await.1["applied"],false);}
    assert_eq!(total(&f).await,0.);assert_eq!(sessions(&f).await,0);let point=f.call("GET",&format!("{base}/recovery"),None).await.1;assert_eq!(point["available"],true);
    reconnect(&f,&mut p).await;f.s.bridge_owners.write().await.insert(p[0].endpoint.clone(),auth::hash(&other));assert_eq!(f.call("POST",&format!("{base}/recovery"),Some(json!({"request_id":uuid::Uuid::new_v4().to_string(),"checkpoint_id":point["checkpoint_id"]}))).await.0,StatusCode::ACCEPTED);
    for i in 0..2{let command=receive(&mut p[i]).await;assert_eq!(command["type"],"prepare_start");bodies[i]["request_id"]=json!(uuid::Uuid::new_v4().to_string());bodies[i]["report"]["start"]=command["start"].clone();bodies[i]["report"]["core_playback_id"]=command["playback_id"].clone();bodies[i]["report"]["gate"]["expires_host_ns"]=command["start"]["expires_host_ns"].clone();}
    let f=restart(f).await;for i in 0..2{let token=if i==0{&other}else{&f.token};assert_eq!(call(&f.app,"POST",&path,Some(token),Some(bodies[i].clone())).await.0,StatusCode::OK);}assert_eq!(total(&f).await,0.);assert_eq!(sessions(&f).await,0);assert_eq!(f.call("GET",&format!("{base}/recovery"),None).await.1["available"],true);
}
#[tokio::test]
async fn group_volume_patch_also_preserves_the_default_legacy_single_track_group() {
    let f=Fixture::new().await;let(track,_)=f.add_audio().await;let mut p=peers(&f,16).await;for peer in &p{f.s.endpoints.write().await.get_mut(&peer.endpoint).unwrap()["capabilities"]["group_volume_v1"]=json!(true);}let req=request(&track,&p);let base=format!("/api/v1/sync/starts/{}",req["request_id"].as_str().unwrap());assert_eq!(f.call("POST","/api/v1/sync/starts",Some(req)).await.0,StatusCode::ACCEPTED);
    let commands=vec![receive(&mut p[0]).await,receive(&mut p[1]).await];for i in 0..2{report(&f,&p[i],ready(&commands[i])).await;}let commits=vec![receive(&mut p[0]).await,receive(&mut p[1]).await];let deadline=f.call("GET",&base,None).await.1["deadline_core_ns"].as_u64().unwrap();tokio::time::sleep(std::time::Duration::from_nanos(deadline.saturating_sub(clock::now_ns())+1_000_000)).await;
    for i in 0..2{let mut released=receipt(&commands[i],&commits[i],&p[i],0,json!([]))["report"].clone();released["phase"]=json!("released");released["final"]=json!(false);released["measured_version"]=json!(1);released["sample_rate"]=json!(48000);report(&f,&p[i],released).await;}
    let(status,zone)=f.call("PATCH",&format!("/api/v1/zones/{}",p[0].zone),Some(json!({"volume":0.25,"muted":true}))).await;assert_eq!(status,StatusCode::OK,"{zone}");assert_eq!(f.call("GET",&base,None).await.1["phase"],"playing");assert_eq!(receive(&mut p[0]).await["type"],"group_volume");assert!(p[1].rx.try_recv().is_err());assert_eq!(total(&f).await,0.);
}
#[tokio::test]
async fn group_volume_patch_keeps_the_released_group_and_rolls_back_without_commands() {
    let(f,mut p,req,commands,commits)=create().await;for peer in &p{f.s.endpoints.write().await.get_mut(&peer.endpoint).unwrap()["capabilities"]["group_volume_v1"]=json!(true);}let base=format!("/api/v1/sync/starts/{}",req["request_id"].as_str().unwrap());let path=format!("/api/v1/zones/{}",p[0].zone);
    assert_eq!(f.call("PATCH",&path,Some(json!({"volume":0.3}))).await.0,StatusCode::CONFLICT,"prepared output must not be cancelled by a volume edit");assert!(p.iter_mut().all(|peer|peer.rx.try_recv().is_err()));
    for i in 0..2 {let mut released=receipt(&commands[i],&commits[i],&p[i],0,json!([]))["report"].clone();released["phase"]=json!("released");released["final"]=json!(false);report(&f,&p[i],released).await;}
    assert_eq!(f.call("GET",&base,None).await.1["phase"],"playing");
    f.s.endpoints.write().await.get_mut(&p[0].endpoint).unwrap()["capabilities"]["group_volume_v1"]=json!(false);assert_eq!(f.call("PATCH",&path,Some(json!({"volume":0.3}))).await.0,StatusCode::CONFLICT);assert!(p.iter_mut().all(|peer|peer.rx.try_recv().is_err()));f.s.endpoints.write().await.get_mut(&p[0].endpoint).unwrap()["capabilities"]["group_volume_v1"]=json!(true);
    for invalid in [json!({"volume":2.}),json!({"volume":"quiet"}),json!({"muted":0})]{assert_eq!(f.call("PATCH",&path,Some(invalid)).await.0,StatusCode::BAD_REQUEST);}
    f.s.db.run(|c|{c.execute_batch("CREATE TRIGGER qa_volume_fail BEFORE UPDATE ON zones BEGIN SELECT RAISE(FAIL,'volume rollback');END;")?;Ok(())}).await.unwrap();assert_eq!(f.call("PATCH",&path,Some(json!({"volume":0.3,"muted":true}))).await.0,StatusCode::INTERNAL_SERVER_ERROR);assert!(p.iter_mut().all(|peer|peer.rx.try_recv().is_err()));assert_eq!(f.call("GET",&path,None).await.1["volume"],1.);
    f.s.db.run(|c|{c.execute_batch("DROP TRIGGER qa_volume_fail")?;Ok(())}).await.unwrap();let(status,zone)=f.call("PATCH",&path,Some(json!({"volume":0.3,"muted":true}))).await;assert_eq!(status,StatusCode::OK,"{zone}");assert_eq!(zone["volume"],0.3);assert_eq!(zone["muted"],true);assert_eq!(zone["playback_id"],commands[0]["playback_id"]);
    let wire=receive(&mut p[0]).await;assert_eq!(wire["type"],"group_volume");assert_eq!(wire["start"],commands[0]["start"]);assert_eq!(wire["playback_id"],commands[0]["playback_id"]);assert_eq!(wire["volume"],0.3);assert_eq!(wire["muted"],true);assert!(p[1].rx.try_recv().is_err());assert_eq!(f.call("GET",&base,None).await.1["phase"],"playing");assert_eq!(total(&f).await,0.);assert_eq!(sessions(&f).await,1);
}
#[tokio::test]
