    let(f,mut p,req,commands,commits)=create().await;let base=format!("/api/v1/sync/starts/{}",req["request_id"].as_str().unwrap());assert_eq!(f.call("POST",&format!("{base}/control"),Some(json!({"request_id":uuid::Uuid::new_v4().to_string(),"action":"pause"}))).await.0,StatusCode::ACCEPTED);for peer in &mut p{assert_eq!(receive(peer).await["type"],"cancel_start");}
    for i in 0..2 {let value=receipt(&commands[i],&commits[i],&p[i],153600,json!([source(&commands[i],153600,false)]));report(&f,&p[i],value["report"].clone()).await;}
    assert_eq!(f.call("GET",&base,None).await.1["phase"],"paused");let(status,zone)=f.call("PATCH",&format!("/api/v1/zones/{}",p[0].zone),Some(json!({"volume":0.3,"muted":true}))).await;assert_eq!(status,StatusCode::OK,"{zone}");assert_eq!(f.call("GET",&base,None).await.1["phase"],"paused");assert!(p.iter_mut().all(|peer|peer.rx.try_recv().is_err()));
    let f=restart(f).await;reconnect(&f,&mut p).await;let point=f.call("GET",&format!("{base}/recovery"),None).await.1;assert_eq!(point["available"],true,"{point}");assert_eq!(f.call("POST",&format!("{base}/recovery"),Some(json!({"request_id":uuid::Uuid::new_v4().to_string(),"checkpoint_id":point["checkpoint_id"]}))).await.0,StatusCode::ACCEPTED);let next=receive(&mut p[0]).await;assert_eq!(next["volume"],0.3);assert_eq!(next["muted"],true);assert_eq!(receive(&mut p[1]).await["volume"],1.);assert_eq!(total(&f).await,0.2);assert_eq!(sessions(&f).await,1);
