#[tokio::test]
async fn group_final_v2_paused_epoch_keeps_dispatch_and_last_output_source_for_replay() {
    let(f,mut p,req,commands,commits)=create().await;let base=format!("/api/v1/sync/starts/{}",req["request_id"].as_str().unwrap());
    assert_eq!(f.call("POST",&format!("{base}/control"),Some(json!({"request_id":uuid::Uuid::new_v4().to_string(),"action":"pause"}))).await.0,StatusCode::ACCEPTED);
    for peer in &mut p{assert_eq!(receive(peer).await["type"],"cancel_start");}
    let bodies=(0..2).map(|i|receipt(&commands[i],&commits[i],&p[i],153600,json!([source(&commands[i],153600,true)]))).collect::<Vec<_>>();
    for i in 0..2{report(&f,&p[i],bodies[i]["report"].clone()).await;}
    let paused=f.call("GET",&base,None).await.1;assert_eq!(paused["phase"],"paused");assert_eq!(paused["playhead"]["queue_index"],1);assert_eq!(total(&f).await,0.2);
    let f=restart(f).await;
    for body in bodies{let(status,result)=f.call("POST",&format!("{base}/final-receipts"),Some(body.clone())).await;assert_eq!(status,StatusCode::OK,"{result}");assert_eq!(f.call("POST",&format!("{base}/final-receipts"),Some(body)).await.1["applied"],false);}
    assert_eq!(total(&f).await,0.2);assert_eq!(sessions(&f).await,1);let point=f.call("GET",&format!("{base}/recovery"),None).await.1;assert_eq!(point["available"],true);assert_eq!(point["queue_index"],1);assert_eq!(point["position"],0.);
}
#[tokio::test]
async fn group_recovery_v2_waits_for_finals_rolls_back_retries_and_reuses_the_group_listen() {
    let(f,mut p,req,commands,commits)=create().await;let f=restart(f).await;let path=format!("/api/v1/sync/starts/{}/recovery",req["request_id"].as_str().unwrap());assert_eq!(f.call("GET",&path,None).await.1["available"],false);
    // Historical six-second counters without waiting or opening an audio output.
    assert_eq!(f.call("GET","/api/v1/sync/starts?active=true",None).await.1["total"],0);
    let listed=f.call("GET","/api/v1/sync/starts?active=true&recoverable=true",None).await.1;assert_eq!(listed["total"],1);assert_eq!(listed["items"][0]["id"],req["request_id"]);
    f.s.db.run(|c|{c.execute("UPDATE sync_output_epochs SET data=json_set(data,'$.deadline_at_ms',?1)",[chrono::Utc::now().timestamp_millis()-10000])?;Ok(())}).await.unwrap();finals(&f,&p,&req,&commands,&commits,[4608000,4531200]).await;let point=f.call("GET",&path,None).await.1;assert_eq!(point["available"],true,"{point}");assert_eq!(point["position"],6.);assert_eq!(point["queue_index"],0);assert_eq!(total(&f).await,6.);reconnect(&f,&mut p).await;
    let body=json!({"request_id":uuid::Uuid::new_v4().to_string(),"checkpoint_id":point["checkpoint_id"]});f.s.db.run(|c|{c.execute_batch("CREATE TRIGGER qa_recover_fail BEFORE INSERT ON sync_group_recoveries BEGIN SELECT RAISE(FAIL,'restore rollback');END;")?;Ok(())}).await.unwrap();assert_eq!(f.call("POST",&path,Some(body.clone())).await.0,StatusCode::INTERNAL_SERVER_ERROR);assert!(p.iter_mut().all(|peer|peer.rx.try_recv().is_err()));assert_eq!(f.call("GET",&path,None).await.1["available"],true);assert_eq!(total(&f).await,6.);
    f.s.db.run(|c|{c.execute_batch("DROP TRIGGER qa_recover_fail")?;Ok(())}).await.unwrap();let(status,value)=f.call("POST",&path,Some(body.clone())).await;assert_eq!(status,StatusCode::ACCEPTED,"{value}");assert_eq!(value["phase"],"preparing");assert_eq!(value["listened_seconds"],6.);assert_eq!(f.call("POST",&path,Some(body.clone())).await.0,StatusCode::OK);
    let mut next=Vec::new();for(i,peer)in p.iter_mut().enumerate(){let command=receive(peer).await;assert_ne!(command["playback_id"],commands[i]["playback_id"]);assert_ne!(command["start"]["host_clock_id"],commands[i]["start"]["host_clock_id"]);assert!(command["start"]["generation"].as_u64()>commands[i]["start"]["generation"].as_u64());assert_eq!(command["position"],6.);next.push(command);assert!(peer.rx.try_recv().is_err());}
    for(i,peer)in p.iter().enumerate(){prepare_v2(&f,peer,&next[i]).await;}
    let mut first=ready(&next[0]);first["measured_version"]=json!(2);first["sample_rate"]=json!(768000);report(&f,&p[0],first).await;assert!(p.iter_mut().all(|peer|peer.rx.try_recv().is_err()));let mut second=ready(&next[1]);second["measured_version"]=json!(2);second["sample_rate"]=json!(768000);report(&f,&p[1],second).await;for peer in &mut p{assert_eq!(receive(peer).await["type"],"commit_start");}
    let current=f.call("GET",&path.replace("/recovery",""),None).await.1;tokio::time::sleep(std::time::Duration::from_nanos(current["deadline_core_ns"].as_u64().unwrap().saturating_sub(clock::now_ns())+1_000_000)).await;
    for(i,frames)in [76800,153600].into_iter().enumerate(){report(&f,&p[i],json!({"type":"state","zone_id":p[i].zone,"core_playback_id":next[i]["playback_id"],"track_id":next[i]["track"]["id"],"status":"playing","measured_version":2,"position":6.+frames as f64/768000.,"frames":frames,"sample_rate":768000})).await;}
    assert!((total(&f).await-6.2).abs()<1e-12);assert_eq!(sessions(&f).await,1);assert_eq!(f.s.db.run(|c|Ok(c.query_row("SELECT SUM(play_count) FROM track_stats",[],|r|r.get::<_,i64>(0))?)).await.unwrap(),1);assert_eq!(f.call("POST",&path,Some(body)).await.0,StatusCode::OK);let stale=json!({"request_id":uuid::Uuid::new_v4().to_string(),"checkpoint_id":point["checkpoint_id"]});assert_eq!(f.call("POST",&path,Some(stale)).await.0,StatusCode::CONFLICT);
}
#[tokio::test]
async fn group_recovery_v2_binds_accounts_capabilities_and_rejects_changed_intent_after_another_restart() {
    let(f,mut p,req,commands,commits)=create().await;let f=restart(f).await;finals(&f,&p,&req,&commands,&commits,[76800,153600]).await;reconnect(&f,&mut p).await;let path=format!("/api/v1/sync/starts/{}/recovery",req["request_id"].as_str().unwrap());let point=f.call("GET",&path,None).await.1;assert_eq!(point["available"],true);let body=json!({"request_id":uuid::Uuid::new_v4().to_string(),"checkpoint_id":point["checkpoint_id"]});
    let(status,_)=f.call("POST","/api/v1/auth/users",Some(json!({"username":"recover-other","password":"correct-recovery-password"}))).await;assert_eq!(status,StatusCode::OK);let(_,login)=call(&f.app,"POST","/api/v1/auth/login",None,Some(json!({"username":"recover-other","password":"correct-recovery-password"}))).await;let token=login["token"].as_str().unwrap();assert_eq!(call(&f.app,"GET",&path,Some(token),None).await.0,StatusCode::FORBIDDEN);f.s.bridge_owners.write().await.insert(p[0].endpoint.clone(),auth::hash(token));assert_eq!(f.call("POST",&path,Some(body.clone())).await.0,StatusCode::CONFLICT);f.s.bridge_owners.write().await.insert(p[0].endpoint.clone(),auth::hash(&f.token));
    f.s.endpoints.write().await.get_mut(&p[1].endpoint).unwrap()["capabilities"]["group_output_final_v2"]=json!(false);assert_eq!(f.call("POST",&path,Some(body.clone())).await.0,StatusCode::CONFLICT);f.s.endpoints.write().await.get_mut(&p[1].endpoint).unwrap()["capabilities"]["group_output_final_v2"]=json!(true);assert!(p.iter_mut().all(|peer|peer.rx.try_recv().is_err()));
    let mut new_request=req.clone();new_request["request_id"]=json!(uuid::Uuid::new_v4().to_string());assert_eq!(f.call("POST","/api/v1/sync/starts",Some(new_request)).await.0,StatusCode::ACCEPTED);assert_eq!(f.call("GET",&path,None).await.1["available"],false,"accepting a new group must revoke the old recovery before its first output");
    assert_eq!(f.call("POST",&format!("/api/v1/zones/{}/stop",p[0].zone),None).await.0,StatusCode::OK);assert_eq!(f.call("GET",&path,None).await.1["available"],false);assert_eq!(f.call("POST",&path,Some(body.clone())).await.0,StatusCode::CONFLICT);let f=restart(f).await;assert_eq!(f.call("GET",&path,None).await.1["available"],false);assert_eq!(f.call("POST",&path,Some(body)).await.0,StatusCode::CONFLICT);
}
#[tokio::test]
async fn group_recovery_v2_preserves_applied_paused_seek_instead_of_old_output_position() {
    let(f,mut p,req,commands,commits)=create().await;let base=format!("/api/v1/sync/starts/{}",req["request_id"].as_str().unwrap());assert_eq!(f.call("POST",&format!("{base}/control"),Some(json!({"request_id":uuid::Uuid::new_v4().to_string(),"action":"pause"}))).await.0,StatusCode::ACCEPTED);for peer in &mut p{assert_eq!(receive(peer).await["type"],"cancel_start");}
    for i in 0..2{let value=receipt(&commands[i],&commits[i],&p[i],153600,json!([source(&commands[i],153600,false)]));report(&f,&p[i],value["report"].clone()).await;}
    assert_eq!(f.call("GET",&base,None).await.1["phase"],"paused");assert_eq!(f.call("POST",&format!("{base}/control"),Some(json!({"request_id":uuid::Uuid::new_v4().to_string(),"action":"seek","queue_index":0,"position":1.5}))).await.0,StatusCode::ACCEPTED);
    let saved=f.s.db.run(|c|Ok(c.query_row("SELECT COUNT(*) FROM sync_output_sources WHERE queue_index=0 AND frames=153600 AND sample_rate=768000",[],|r|r.get::<_,i64>(0))?)).await.unwrap();assert_eq!(saved,2,"paused seek placeholders must not overwrite confirmed output facts");
    let f=restart(f).await;for i in 0..2{let body=receipt(&commands[i],&commits[i],&p[i],153600,json!([source(&commands[i],153600,false)]));assert_eq!(f.call("POST",&format!("{base}/final-receipts"),Some(body)).await.0,StatusCode::OK);}assert_eq!(total(&f).await,0.2,"late identical finals must not add the already confirmed cohort duration");let path=format!("{base}/recovery");let point=f.call("GET",&path,None).await.1;assert_eq!(point["available"],true,"{point}");assert_eq!(point["position"],1.5);reconnect(&f,&mut p).await;
    let(status,value)=f.call("POST",&path,Some(json!({"request_id":uuid::Uuid::new_v4().to_string(),"checkpoint_id":point["checkpoint_id"]}))).await;assert_eq!(status,StatusCode::ACCEPTED,"{value}");assert_eq!(total(&f).await,0.2);assert_eq!(sessions(&f).await,1);for peer in &mut p{assert_eq!(receive(peer).await["position"],1.5);}
}

#[tokio::test]
async fn group_recovery_v2_uses_the_furthest_preloaded_source_without_reopening_completed_sources() {
    let(f,mut p,req,commands,commits)=create().await;let f=restart(f).await;let base=format!("/api/v1/sync/starts/{}",req["request_id"].as_str().unwrap());
    for i in 0..2 {
        let endpoint=p[i].endpoint.clone();let playback=f.s.db.run(move|c|Ok(c.query_row("SELECT playback_id FROM sync_output_sources WHERE endpoint_id=?1 AND queue_index=1",[endpoint],|r|r.get::<_,String>(0))?)).await.unwrap();let frames=if i==0{153600}else{115200};let current=json!({"playback_id":playback,"track_id":commands[i]["track"]["id"],"frames":frames,"position":frames as f64/768000.,"ended":false});let body=receipt(&commands[i],&commits[i],&p[i],76800+frames,json!([source(&commands[i],76800,true),current]));assert_eq!(f.call("POST",&format!("{base}/final-receipts"),Some(body)).await.0,StatusCode::OK);
    }
    let point=f.call("GET",&format!("{base}/recovery"),None).await.1;assert_eq!(point["available"],true,"{point}");assert_eq!(point["queue_index"],1);assert_eq!(point["position"],0.2);assert!((total(&f).await-0.3).abs()<1e-12);reconnect(&f,&mut p).await;
    let(status,value)=f.call("POST",&format!("{base}/recovery"),Some(json!({"request_id":uuid::Uuid::new_v4().to_string(),"checkpoint_id":point["checkpoint_id"]}))).await;assert_eq!(status,StatusCode::ACCEPTED,"{value}");assert_eq!(value["playhead"]["queue_index"],1);assert!((total(&f).await-0.3).abs()<1e-12);assert_eq!(sessions(&f).await,2);for peer in &mut p{assert_eq!(receive(peer).await["position"],0.2);}
}
